CREATE EXTENSION IF NOT EXISTS citext;
CREATE TABLE IF NOT EXISTS smtp_profiles (id bigserial primary key,owner_id bigint not null references users(id),name text not null,host text not null,port integer not null,username text not null,password_ciphertext text not null,use_tls boolean not null default true,created_at timestamptz not null default now(),unique(owner_id,name));
CREATE TABLE IF NOT EXISTS suppressions (email citext primary key,reason text not null default 'manual',created_at timestamptz not null default now());
CREATE TABLE IF NOT EXISTS send_attempts (id bigserial primary key,owner_id bigint not null references users(id),contact_id bigint not null references contacts(id),profile_id bigint not null references smtp_profiles(id),idempotency_key text not null,status text not null check(status in ('sending','sent','uncertain','failed')),subject text not null,body text not null,error_code text,error_message text,sent_at timestamptz,created_at timestamptz not null default now(),unique(owner_id,idempotency_key));
